-- devuelve la mención a texto plano.

DELETE FROM editorial_entity_references
 WHERE editorial_document_id = '0e595e53-e607-4b03-973b-85d73a8cb945'::uuid
   AND occurrence_id = '9be5d53b-fb72-4ec9-b3a4-c3617e65475a'::uuid;
UPDATE editorial_documents SET document = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Julito Deschamps was a Dominican bolero singer, pianist, guitarist and composer, and the defining voice of the country’s late-night music. He worked in small rooms for most of his life and refused the things that would have made him famous.","type":"text"}]},{"type":"paragraph","content":[{"text":"The boîte","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"A boîte is a small dark room with a piano, a few tables and no stage worth the name. Santo Domingo and Santiago had a circuit of them through the sixties and seventies, and that circuit is where Dominican bolero actually lived — not on the radio, not in the ballrooms, but at close range in front of forty people at two in the morning.","type":"text"}]},{"type":"paragraph","content":[{"text":"He was the figure of that world. The voice is powerful and complaining at once, the diction exact, and everything about the delivery assumes the listener is close enough to hear him breathe.","type":"text"}]},{"type":"paragraph","content":[{"text":"The mathematician","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Musicians called him el matemático because of how he chose songs. His repertoire is a very deliberate list — Sortilegio, La Gloria Eres Tú, Delirio, ¿Cómo Fue?, Miénteme, Tres Palabras, Pecadora, Te Necesito, Yo Vivo Mi Vida, Amor Perdido — and almost everything he picked up became identified with him.","type":"text"}]},{"type":"paragraph","content":[{"text":"He came into it as a singer with Papatín Ovalles’s orchestra in 1952, and his first recording did not arrive until 1960: Tu Palabra y La Mía, written by Antonio Morel. What made his name was Será Muy Fácil, by Jesús Torres Tejeda. Llorará Por Mí, Dos Palabras, Negra Soledad, Poquita Fe, Háblame, Olvídate de Mí, Torpeza, Cosas del Alma, Tú Mi Delirio and Como Duele Una Traición followed.","type":"text"}]},{"type":"paragraph","content":[{"text":"Sólo Para Amarte, Llorarás Por Mí and a record made with the Cuban singer Olga Guillot are among the albums.","type":"text"}]},{"type":"paragraph","content":[{"text":"The songs that were banned","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"In 1969 he recorded two Christmas songs, Navidad 69 and Aguinaldo 69. They were the first compositions ever recorded of a writer named Mundito Espinal, and by Espinal’s own reading their lyrics were calls to rise against the government of ","type":"text"},{"type":"artistReference","attrs":{"artistId":"f01002fa-68e4-4fa9-a8cc-91ab9004cea9","displayText":"Joaquín Balaguer","occurrenceId":"6cae823d-e465-4b03-8e8e-12204766403c"}},{"text":".","type":"text"}]},{"type":"paragraph","content":[{"text":"The Comisión de Espectáculos Públicos y Radiofonía banned them. A third, Dictadura con Apoyo Popular, is named in the accounts as following.","type":"text"}]},{"type":"paragraph","content":[{"text":"It is worth being exact about whose songs those were, because almost every page that repeats the story says Deschamps was recording his own compositions. He was not. He was the singer a young writer got, and being sung by him was how a composer arrived — which is a description of what he was worth in that decade.","type":"text"}]},{"type":"paragraph","content":[{"text":"The refusal","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"He never appeared on television. In a country where a career was built on a variety programme and where every contemporary of his was on screen, he simply did not go, and a Dominican newspaper was still writing about that decision twenty-eight years after his death.","type":"text"}]},{"type":"paragraph","content":[{"text":"That is why he is remembered the way he is: not through footage, because there is almost none, but through recordings and through people who were in the room. The bohemian who refused the noise is the phrase that keeps getting used about him, and it is accurate about the career as well as the voice.","type":"text"}]},{"type":"paragraph","content":[{"text":"He died in 1985, at fifty-five. His son recorded too, a generation later and in a form he would not have recognised: Papo, of the merenrap duo Sandy & Papo MC, who also died young.","type":"text"}]}]}'::jsonb,
       revision = 4, updated_at = now()
 WHERE id = '0e595e53-e607-4b03-973b-85d73a8cb945'::uuid;

DELETE FROM editorial_entity_references
 WHERE editorial_document_id = 'cff3f57d-d532-4f96-97e5-d56aa1bfe581'::uuid
   AND occurrence_id = '6b673856-7e6e-4b09-a749-737c08e741fe'::uuid;
UPDATE editorial_documents SET document = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Julito Deschamps fue cantante de boleros, pianista, guitarrista y compositor dominicano, y la voz que define la música nocturna del país. Trabajó en salones pequeños casi toda su vida y rechazó lo que lo habría vuelto famoso.","type":"text"}]},{"type":"paragraph","content":[{"text":"La boîte","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Una boîte es un salón chiquito y oscuro con un piano, unas mesas y ninguna tarima que merezca el nombre. Santo Domingo y Santiago tuvieron un circuito de ellas durante los sesenta y los setenta, y ahí fue donde de verdad vivió el bolero dominicano: no en la radio, no en los salones de baile, sino a corta distancia delante de cuarenta personas a las dos de la mañana.","type":"text"}]},{"type":"paragraph","content":[{"text":"Él era la figura de ese mundo. La voz es potente y quejumbrosa a la vez, la dicción exacta, y todo en la entrega da por sentado que el que oye está lo bastante cerca para oírlo respirar.","type":"text"}]},{"type":"paragraph","content":[{"text":"El matemático","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Los músicos le decían el matemático por cómo escogía las canciones. Su repertorio es una lista muy deliberada —Sortilegio, La Gloria Eres Tú, Delirio, ¿Cómo Fue?, Miénteme, Tres Palabras, Pecadora, Te Necesito, Yo Vivo Mi Vida, Amor Perdido— y casi todo lo que agarró terminó identificándose con él.","type":"text"}]},{"type":"paragraph","content":[{"text":"Entró como cantante en la orquesta de Papatín Ovalles en 1952, y su primera grabación no llegó hasta 1960: Tu Palabra y La Mía, de Antonio Morel. Lo que le hizo el nombre fue Será Muy Fácil, de Jesús Torres Tejeda. Detrás vinieron Llorará Por Mí, Dos Palabras, Negra Soledad, Poquita Fe, Háblame, Olvídate de Mí, Torpeza, Cosas del Alma, Tú Mi Delirio y Como Duele Una Traición.","type":"text"}]},{"type":"paragraph","content":[{"text":"Entre los álbumes están Sólo Para Amarte, Llorarás Por Mí y un disco hecho con la cubana Olga Guillot.","type":"text"}]},{"type":"paragraph","content":[{"text":"Las canciones prohibidas","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"En 1969 grabó dos aguinaldos, Navidad 69 y Aguinaldo 69. Eran las primeras composiciones grabadas de un autor llamado Mundito Espinal, y según la lectura del propio Espinal sus letras eran llamados a la sublevación contra el gobierno de ","type":"text"},{"type":"artistReference","attrs":{"artistId":"f01002fa-68e4-4fa9-a8cc-91ab9004cea9","displayText":"Joaquín Balaguer","occurrenceId":"a534cebc-a7a9-4aa4-b676-f51bc5f3634d"}},{"text":".","type":"text"}]},{"type":"paragraph","content":[{"text":"La Comisión de Espectáculos Públicos y Radiofonía las prohibió. Los relatos nombran una tercera detrás, Dictadura con Apoyo Popular.","type":"text"}]},{"type":"paragraph","content":[{"text":"Conviene ser exacto sobre de quién eran esas canciones, porque casi todas las páginas que repiten la historia dicen que Deschamps grababa composiciones suyas. No lo eran. Él era el cantante que un autor joven consiguió, y que él te cantara era la manera en que un compositor llegaba, lo cual describe bastante bien cuánto valía en esa década.","type":"text"}]},{"type":"paragraph","content":[{"text":"La negativa","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Nunca apareció en televisión. En un país donde una carrera se construía en un programa de variedades y donde todos sus contemporáneos estaban en pantalla, él sencillamente no fue, y un periódico dominicano seguía escribiendo sobre esa decisión veintiocho años después de su muerte.","type":"text"}]},{"type":"paragraph","content":[{"text":"Por eso se le recuerda como se le recuerda: no por las imágenes, porque casi no hay, sino por las grabaciones y por la gente que estuvo en el salón. El bohemio que le dijo que no al ruido es la frase que se le repite, y es exacta tanto sobre la carrera como sobre la voz.","type":"text"}]},{"type":"paragraph","content":[{"text":"Murió en 1985, a los cincuenta y cinco. Su hijo también grabó, una generación después y en una forma que él no habría reconocido: Papo, del dúo de merenrap Sandy & Papo MC, que también murió joven.","type":"text"}]}]}'::jsonb,
       revision = 4, updated_at = now()
 WHERE id = 'cff3f57d-d532-4f96-97e5-d56aa1bfe581'::uuid;

COMMIT;
